// Мигание светодиода: 5 секунд выключен, затем короткая вспышка
// Подключи светодиод к пину 13 (или встроенный LED на плате)

const int LED_PIN = 13;           // пин светодиода
const unsigned long PERIOD = 5000; // период 5 секунд
const unsigned long ON_TIME = 500; // длительность вспышки 0.5 сек

unsigned long previousMillis = 0;
bool ledState = false;
bool pulseStarted = false;
unsigned long pulseStart = 0;

void setup() {
  pinMode(LED_PIN, OUTPUT);
  digitalWrite(LED_PIN, LOW);
}

void loop() {
  unsigned long currentMillis = millis();

  // Если ещё не было вспышки и прошло 5 секунд — включаем
  if (!pulseStarted && currentMillis - previousMillis >= PERIOD) {
    digitalWrite(LED_PIN, HIGH);
    ledState = true;
    pulseStarted = true;
    pulseStart = currentMillis;
  }

  // Выключаем через ON_TIME
  if (pulseStarted && currentMillis - pulseStart >= ON_TIME) {
    digitalWrite(LED_PIN, LOW);
    ledState = false;
    pulseStarted = false;
    previousMillis = currentMillis;
  }
}
